            String prop = c.proposition().toString();
            Matcher m = p.matcher(prop);
            System.out.println(prop);
            int start = 0;
            while (m.find(start)) {
                String name = prop.substring(m.start(), m.end() - 1);
                if (Character.isLowerCase(name.charAt(0))) {
