                unitTests.stream().map(i -> "btrPlace;" + i).collect(Collectors.joining("\n", "", "\n")) +
                safeTests.stream().map(i -> "safePlace;" + i).collect(Collectors.joining("\n", "", "\n"));
        Path path = Paths.get(root, "sloc.csv");
        Files.write(path, sb.getBytes());
    }

